const t={remoteControl:{intro:{t:0,b:{t:2,i:[{t:3}],s:"प्रिंटर पर लगी FilaMind स्क्रीन को कमांड भेजें।"}},status:{ready:{t:0,b:{t:2,i:[{t:3}],s:"कमांड बस से कनेक्ट है"}},down:{t:0,b:{t:2,i:[{t:3}],s:"कमांड बस से कनेक्ट हो रहा है…"}}},show:{title:{t:0,b:{t:2,i:[{t:3}],s:"स्क्रीन पर दिखाएं"}},status:{t:0,b:{t:2,i:[{t:3}],s:"स्थिति"}},control:{t:0,b:{t:2,i:[{t:3}],s:"नियंत्रण"}},settings:{t:0,b:{t:2,i:[{t:3}],s:"सेटिंग्स"}}},locate:{title:{t:0,b:{t:2,i:[{t:3}],s:"स्क्रीन ढूंढें"}},hint:{t:0,b:{t:2,i:[{t:3}],s:"स्क्रीन को फ्लैश करें ताकि आप पहचान सकें कि यह किस प्रिंटर की है।"}},button:{t:0,b:{t:2,i:[{t:3}],s:"स्क्रीन ढूंढें"}}},message:{title:{t:0,b:{t:2,i:[{t:3}],s:"संदेश भेजें"}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:"स्क्रीन पर दिखाने के लिए छोटा संदेश लिखें…"}},level:{t:0,b:{t:2,i:[{t:3}],s:"स्तर"}},info:{t:0,b:{t:2,i:[{t:3}],s:"जानकारी"}},warn:{t:0,b:{t:2,i:[{t:3}],s:"चेतावनी"}},send:{t:0,b:{t:2,i:[{t:3}],s:"भेजें"}}},sent:{t:0,b:{t:2,i:[{t:3}],s:"भेज दिया"}},help:{button:{t:0,b:{t:2,i:[{t:3}],s:"मदद"}},title:{t:0,b:{t:2,i:[{t:3}],s:"रिमोट नियंत्रण — गाइड"}},close:{t:0,b:{t:2,i:[{t:3}],s:"बंद करें"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"यह क्या करता है"}},body:{t:0,b:{t:2,i:[{t:3}],s:"यह पैनल यहीं से प्रिंटर पर लगी FilaMind टचस्क्रीन को नियंत्रित करता है: इसका टैब बदलें, इस पर छोटा संदेश दिखाएं, या इसे फ्लैश करें ताकि आप पहचान सकें कि यह कौन-सा प्रिंटर है। ये केवल डिस्प्ले से जुड़े संकेत हैं — ये कभी प्रिंटर को हिलाते नहीं और न ही कोई सेटिंग बदलते हैं।"}}},commands:{title:{t:0,b:{t:2,i:[{t:3}],s:"कमांड्स"}},body:{t:0,b:{t:2,i:[{t:3}],s:"दिखाएं स्क्रीन को उसके स्थिति, नियंत्रण या सेटिंग्स टैब पर ले जाता है। ढूंढें स्क्रीन को कुछ सेकंड के लिए फ्लैश करता है। संदेश एक छोटा नोट (जानकारी या चेतावनी) दिखाता है। कमांड्स इस प्रिंटर की किसी भी FilaMind स्क्रीन तक पहुंचते हैं; जब तक कमांड बस कनेक्ट हो रही होती है, तब तक कुछ भी नहीं भेजा जाता।"}}}}},requiresScreen:{t:0,b:{t:2,i:[{t:3}],s:"ये नियंत्रण प्रिंटर पर FilaMind स्क्रीन को संचालित करते हैं। इन्हें उपयोग करने के लिए इस प्रिंटर पर FilaMind 3D इंस्टॉल करें।"}}}};export{t as default};
